window.__PAGES=window.__PAGES||{};window.__PAGES["pages/settings-channels-wa-web.html"]="<!-- Settings: WhatsApp Web Channel -->\n<style>\n.st-wa2-status{display:flex;align-items:center;gap:12px;padding:16px;background:var(--card);border:1px solid var(--border);border-radius:var(--radius);margin-bottom:20px}\n.st-wa2-status .dot{width:10px;height:10px;border-radius:50%;flex-shrink:0}\n.st-wa2-status .dot.on{background:var(--ok)}.st-wa2-status .dot.off{background:var(--danger)}\n.st-qr-box{width:220px;height:220px;border:2px dashed var(--border);border-radius:var(--radius);display:grid;place-items:center;margin:20px 0;font-size:16px;color:var(--muted);background:var(--card)}\n.badge{display:inline-block;padding:3px 10px;border-radius:10px;font-size:11px;font-weight:700}\n.badge.ok{background:#dcfce7;color:#15803d}.badge.err{background:#fef2f2;color:var(--danger)}\n</style>\n\n<div class=\"settings-layout\">\n  <aside class=\"settings-sidenav\">\n    <div class=\"sn-title\">Organisasi</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-general')\">Umum</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-members')\">Anggota</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-roles')\">Role & Izin</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-tags')\">Tag</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-shift-hours')\">Jam Shift</div>\n    <div class=\"sn-title\">Inbox</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-assignments')\">Assignment</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-team-inbox')\">Tim Inbox</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-sla')\">SLA</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-csat')\">CSAT</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-macros')\">Makro</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-tickets')\">Tiket</div>\n    <div class=\"sn-title\">Channel</div>\n    <div class=\"sn-item\" onclick=\"go('settings/channels-whatsapp-api')\">WhatsApp API</div>\n    <div class=\"sn-item active\" onclick=\"go('settings/channels-whatsapp-web')\">WhatsApp Web</div>\n    <div class=\"sn-item\" onclick=\"go('settings/channels-widget')\">Widget</div>\n    <div class=\"sn-title\">Billing</div>\n    <div class=\"sn-item\" onclick=\"go('settings/billing-cost')\">Kontrol Biaya</div>\n    <div class=\"sn-title\">Developer</div>\n    <div class=\"sn-item\" onclick=\"go('settings/developer-webhook')\">Webhook</div>\n  </aside>\n\n  <div class=\"settings-body\">\n    <h2 style=\"margin-bottom:4px\">WhatsApp Web</h2>\n    <p style=\"font-size:13px;color:var(--muted);margin-bottom:20px\">Koneksi WhatsApp Web via scan QR code. Cocok untuk nomor personal.</p>\n\n    <div class=\"st-wa2-status\" id=\"waWebStatus\">\n      <span class=\"dot\" id=\"waWebDot\"></span>\n      <span id=\"waWebBadge\"></span>\n      <span style=\"margin-left:auto;font-size:13px\" id=\"waWebNum\"></span>\n    </div>\n\n    <div class=\"card\" style=\"padding:16px;max-width:400px\">\n      <div style=\"font-size:12px;color:var(--muted);margin-bottom:8px\">Status: <strong id=\"waWebStatusText\">-</strong></div>\n      <div style=\"font-size:12px;color:var(--muted);margin-bottom:8px\">Nomor: <strong id=\"waWebNumber\">-</strong></div>\n    </div>\n\n    <div class=\"st-qr-box\" id=\"qrBox\">\n      📷 Scan QR\n    </div>\n\n    <div style=\"display:flex;gap:8px\">\n      <button class=\"btn primary\" id=\"waWebBtn\" onclick=\"toggleWaWeb()\">Putuskan</button>\n    </div>\n  </div>\n</div>\n\n<script>\n(function(){\n  const c=DB.settings.channels.whatsappWeb;\n  const connected=c.connected;\n  document.getElementById('waWebDot').className='dot '+(connected?'on':'off');\n  document.getElementById('waWebBadge').innerHTML=connected\n    ?'<span class=\"badge ok\">Terhubung</span>'\n    :'<span class=\"badge err\">Terputus</span>';\n  document.getElementById('waWebNum').textContent=c.number||'';\n  document.getElementById('waWebStatusText').textContent=connected?(c.status||'active'):'Terputus';\n  document.getElementById('waWebNumber').textContent=c.number||'-';\n  document.getElementById('waWebBtn').textContent=connected?'Putuskan':'Hubungkan';\n  document.getElementById('qrBox').style.display=connected?'none':'grid';\n})();\n\nfunction toggleWaWeb(){\n  const c=DB.settings.channels.whatsappWeb;\n  if(c.connected){\n    DB.settings.channels.whatsappWeb={...c,connected:false,status:'disconnected'};\n    showToast('WhatsApp Web berhasil diputuskan');\n  }else{\n    DB.settings.channels.whatsappWeb={...c,connected:true,status:'active',number:c.number||'+628****7778'};\n    showToast('WhatsApp Web berhasil terhubung');\n  }\n  saveStore();\n  go('settings/channels-whatsapp-web');\n}\n</script>\n";
